{"output": "from collections import Counter


def _runs(values, background):
    result = []
    i = 0
    while i < len(values):
        if values[i] == background:
            i += 1
            continue
        color = values[i]
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        result.append((i, j, color))
        i = j
    return result


def transform(grid):
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []

    left = _runs([grid[r][0] for r in range(height)], background)
    right = _runs([grid[r][-1] for r in range(height)], background)
    for a in left:
        for b in right:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                candidates.append((a[1] - a[0], "vertical", a, b))

    top = _runs(grid[0], background)
    bottom = _runs(grid[-1], background)
    for a in top:
        for b in bottom:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                candidates.append((a[1] - a[0], "horizontal", a, b))

    if not candidates:
        return out
    _, orientation, first, second = max(candidates, key=lambda x: x[0])
    rail_color = first[2]
    markers = []

    if orientation == "vertical":
        for r in range(height):
            if first[0] <= r < first[1]:
                side = 0
            elif second[0] <= r < second[1]:
                side = 1
            else:
                continue
            for c in range(1, width - 1):
                color = grid[r][c]
                if color != background and color != rail_color:
                    markers.append((r, c, color, side))

        # Extend each marker ray toward its own boundary run.
        for r, c, color, side in markers:
            if side == 0:
                for cc in range(1, c):
                    out[r][cc] = color
            else:
                for cc in range(c + 1, width - 1):
                    out[r][cc] = color

    else:
        for c in range(width):
            if first[0] <= c < first[1]:
                side = 0
            elif second[0] <= c < second[1]:
                side = 1
            else:
                continue
            for r in range(1, height - 1):
                color = grid[r][c]
                if color != background and color != rail_color:
                    markers.append((r, c, color, side))

        # Extend each marker ray toward its own boundary run.
        for r, c, color, side in markers:
            if side == 0:
                for rr in range(1, r):
                    out[rr][c] = color
            else:
                for rr in range(r + 1, height - 1):
                    out[rr][c] = color

    for r, c, color, side in markers:
        out[r][c] = 4
    return out


if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))", "exit_code": 0, "error": null}

