{"output": "from collections import Counter


def _runs(values, background):
    result = []
    i = 0
    while i < len(values):
        if values[i] == background:
            i += 1
            continue
        color = values[i]
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        result.append((i, j, color))
        i = j
    return result


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []

    left = _runs([grid[r][0] for r in range(h)], bg)
    right = _runs([grid[r][-1] for r in range(h)], bg)
    for a in left:
        for b in right:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                candidates.append((a[1] - a[0], "vertical", a, b))
    top = _runs(grid[0], bg)
    bottom = _runs(grid[-1], bg)
    for a in top:
        for b in bottom:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                candidates.append((a[1] - a[0], "horizontal", a, b))
    if not candidates:
        return out

    _, axis, first, second = max(candidates, key=lambda item: item[0])
    markers = []
    if axis == "vertical":
        for run, side in ((first, 0), (second, 1)):
