 "content": "from collections import Counter


def _edge_runs(values, background):
    runs = []
    i = 0
    while i < len(values):
        if values[i] == background:
            i += 1
            continue
        color = values[i]
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        runs.append((i, j, color))
        i = j
    return runs


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    left = _edge_runs([grid[r][0] for r in range(h)], background)
    right = _edge_runs([grid[r][-1] for r in range(h)], background)
    rails = None
    for a in left:
        for b in right:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                rails = (a, b)
                break
        if rails:
            break
    if rails is None:
        return out

    left_run, right_run = rails
    markers = []
    for run, side in ((left_run, 0), (right_run, 1)):
        for r in range(run[0], run[1]):
            for c in range(1, w - 1):
                color = grid[r][c]
                if color != background and color != left_run[2]:
                    markers.append((r, c, color, side))

    for r, c, color, side in markers:
        # Extend the marker toward the rail on its own side.
        if side == 0:
            for cc in range(1, c):
                out[r][cc] = color
            opposite_row = right_run[0] + (r - left_run[0])
            # Project the marker's color across the opposite rail segment.
            for cc in range(0, w - 1):
                out[opposite_row][cc] = color
        else:
            for cc in range(c + 1, w - 1):
                out[r][cc] = color
            opposite_row = left_run[0] + (r - right_run[0])
            for cc in range(1, w):
                out[opposite_row][cc] = color
        out[r][c] = 4

    return out


